            exported: "Exported on", start: "Start of the conversation", startText: "This is the very first message of your conversation.",
            search: "Search in the conversation", noResult: "No result", edited: "edited", pinned: "pinned",
            reply: "Reply", deleted: "Original message not found", memberSince: "Discord member since", about: "About me",
            inConv: "In this conversation", msgCount: "{n} message(s)", bottom: "Jump to latest", top: "Jump to first message",
            notSaved: "File not included in the export", openOriginal: "open original", download: "Save", close: "Close",
